draw:
var th = p.angle * Math.PI / 180;
var A = p.magA, B = p.magB;
var pad = 30;
var span = 13;
var s = Math.min((W - 2 * pad) / (1.9 * span), (H - 2 * pad) / (1.5 * span));
var ox = W * 0.24, oy = H * 0.80;
var X = function (x) { return ox + x * s; };
var Y = function (y) { return oy - y * s; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x1, y1, x2, y2, col, wid) {
  ctx.strokeStyle = col; ctx.lineWidth = wid;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), hl = 9;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - hl * Math.cos(a - 0.4), y2 - hl * Math.sin(a - 0.4));
  ctx.lineTo(x2 - hl * Math.cos(a + 0.4), y2 - hl * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

var ax = A, ay = 0;
var bx = B * Math.cos(th), by = B * Math.sin(th);

// parallelogram
ctx.fillStyle = C.faint;
ctx.beginPath();
ctx.moveTo(X(0), Y(0));
ctx.lineTo(X(ax), Y(ay));
ctx.lineTo(X(ax + bx), Y(ay + by));
ctx.lineTo(X(bx), Y(by));
ctx.closePath(); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(X(ax), Y(ay)); ctx.lineTo(X(ax + bx), Y(ay + by)); ctx.lineTo(X(bx), Y(by));
ctx.stroke();
ctx.setLineDash([]);

// height = B sin(th)
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.4;
ctx.setLineDash([5, 4]);
ctx.beginPath(); ctx.moveTo(X(bx), Y(by)); ctx.lineTo(X(bx), Y(0)); ctx.stroke();
ctx.setLineDash([]);

arrow(X(0), Y(0), X(ax), Y(ay), C.rule, 2.5);
arrow(X(0), Y(0), X(bx), Y(by), C.accent, 2.5);

ctx.strokeStyle = C.figure; ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.arc(X(0), Y(0), 26, 0, -th, true); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("A", X(ax) + 6, Y(0) + 16);
ctx.fillText("B", X(bx) + 6, Y(by) - 6);
ctx.fillText("h = B sin(theta) = " + (B * Math.sin(th)).toFixed(2), X(bx) + 8, Y(by / 2));
ctx.fillStyle = C.figure;
ctx.fillText(p.angle.toFixed(0) + " deg", X(0) + 30, Y(0) - 8);

// the out-of-page vector, drawn as a circled dot or cross to the right
var cx = W * 0.86, cy = H * 0.30, r = 13;
var area = A * B * Math.sin(th);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.accent;
if (area >= 0) {
  ctx.beginPath(); ctx.arc(cx, cy, 3.5, 0, Math.PI * 2); ctx.fill();
} else {
  ctx.beginPath();
  ctx.moveTo(cx - 7, cy - 7); ctx.lineTo(cx + 7, cy + 7);
  ctx.moveTo(cx + 7, cy - 7); ctx.lineTo(cx - 7, cy + 7);
  ctx.stroke();
}
ctx.fillStyle = C.ink;
ctx.fillText("A x B", cx - 18, cy + r + 16);
ctx.fillText(area >= 0 ? "out of page" : "into page", cx - 30, cy + r + 32);

out.note = "|A x B| = |A||B|sin(theta) = " + A.toFixed(1) + " x " + B.toFixed(1) + " x " + Math.abs(Math.sin(th)).toFixed(3) + " = " + Math.abs(area).toFixed(2) + " = shaded area" + (Math.abs(area) < 0.05 ? "   (parallel: zero)" : "");
